{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill would add child trafficking prevention and awareness education to the list in Tennessee Code Annotated, Section 49-1-1002(a), by replacing specified wording.",
      "rationale": "Identifies the amended provision and the added subject. The exact placement within the list is not material to its legal meaning."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "It would also delete subdivision (a)(13)(B) and the second sentence of subsection (d) of Section 49-6-1304",
      "rationale": "Explicitly identifies the subdivision deleted and its statutory section."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "It would also delete subdivision (a)(13)(B) and the second sentence of subsection (d) of Section 49-6-1304",
      "rationale": "Explicitly identifies the deleted sentence, subsection, and statutory section."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "It defines “child trafficking” as a human trafficking offense under the cited statute involving a victim under 18.",
      "rationale": "Conveys both the incorporation of the statutory human trafficking offense definition and the victim age limit."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "HB1527 would require child trafficking prevention and awareness education as part of health education in every grade from kindergarten through grade 12 in public schools.",
      "rationale": "Covers the mandatory instruction, health education placement, public school scope, and all K–12 grades."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Local education agencies and public charter schools would have to use state board of education health education standards and provide instruction that is appropriate for students’ ages and grades, with developmentally appropriate instruction and skill building advancing each year.",
      "rationale": "Includes both responsible entities, the governing standards, age and grade appropriateness, and annual developmental progression."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "They may use a qualified healthcare professional or social worker to help teach it, if that person meets the cited requirements for helping teach family life.",
      "rationale": "Conveys the permission for the previously identified entities, eligible professionals, assisting role, and family-life teaching qualification condition."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "Starting August 1, 2026, and every August 1 after that, each local school board and public charter school governing body would have to send an implementation plan to the education commissioner and publish it on the school system’s or charter school’s website. The plan must describe how instruction will be delivered at each grade level, the instructor’s professional qualifications, and the materials and resources used.",
      "rationale": "Includes the initial and recurring deadlines, responsible bodies, submission recipient, website publication, and all required plan contents."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "Starting July 1, 2027, and every July 1 after that, they would also have to report to the commissioner, verify that the instruction was provided in the previous school year, and include the same information.",
      "rationale": "Carries forward the responsible governing bodies and plan information, and states the reporting deadlines, recipient, and verification of instruction during the preceding school year."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "The act would take effect upon becoming law but apply to the 2026–2027 school year and later school years.",
      "rationale": "States both the effective-date trigger and the initial and subsequent school years of application."
    }
  ]
}
